#!/usr/bin/env python3
"""Re-fill to 120 columns every comment paragraph that holds a line this PR added past 120 characters."""
import re
import subprocess

ROOT = "/Users/gabe/Projects/caliper/.claude/worktrees/agent-afbe23f186d326886"
WIDTH = 120
COMMENT = re.compile(r"^(\s*)(///|//!|//)( ?)(.*)$")
ITEM = re.compile(r"^(- |\d+\. |\* )")

diff = subprocess.run(["git", "diff", "origin/main", "-U0", "--", "crates"], cwd=ROOT, capture_output=True,
                      text=True).stdout
long_lines = {}
file = None
for line in diff.splitlines():
    if line.startswith("+++ "):
        file = line[6:]
    elif line.startswith("@@"):
        number = int(line.split("+")[1].split(",")[0].split(" ")[0]) - 1
    elif line.startswith("+"):
        number += 1
        if len(line) - 1 > WIDTH:
            long_lines.setdefault(file, []).append(number)

for path, numbers in long_lines.items():
    full = f"{ROOT}/{path}"
    lines = open(full).read().split("\n")
    for number in sorted(numbers, reverse=True):
        index = number - 1
        match = COMMENT.match(lines[index])
        if not match:
            print(f"{path}:{number}: not a comment, left: {len(lines[index])}")
            continue
        indent, marker = match.group(1), match.group(2)

        def text_of(i):
            m = COMMENT.match(lines[i]) if 0 <= i < len(lines) else None
            if not m or m.group(1) != indent or m.group(2) != marker:
                return None
            return m.group(4)

        start = index
        while True:
            here = text_of(start)
            above = text_of(start - 1)
            if here is None or ITEM.match(here.lstrip()) and here == here.lstrip() or here.startswith("```"):
                break
            if above is None or above.strip() == "" or above.startswith("```"):
                break
            if here.startswith(" ") and not above.startswith(" ") and not ITEM.match(above):
                break
            start -= 1
        end = index
        while True:
            below = text_of(end + 1)
            if below is None or below.strip() == "" or below.startswith("```") or ITEM.match(below):
                break
            end += 1
        first = text_of(start)
        item = ITEM.match(first)
        hang = " " * len(item.group(0)) if item else ""
        words = " ".join(text_of(i).strip() for i in range(start, end + 1)).split()
        head = f"{indent}{marker} "
        out, current = [], head
        for word in words:
            prefix_len = len(head) if not out else len(head) + len(hang)
            if len(current) + (0 if current.endswith(" ") else 1) + len(word) > WIDTH and current.strip() != marker:
                out.append(current.rstrip())
                current = head + hang
            current += ("" if current.endswith(" ") else " ") + word
        out.append(current.rstrip())
        lines[start:end + 1] = out
        print(f"{path}:{number}: re-filled lines {start + 1}-{end + 1} into {len(out)}")
    open(full, "w").write("\n".join(lines))

